/*
 * app.js - bootstrap, state, and wiring.
 *
 * Data comes from ./data/*.json, generated by tools/export_talents.py from
 * the same DBCs that ship to the client.  Nothing is fetched from Wowhead:
 * it has no knowledge of Alonecraft's custom talents, which is the entire
 * reason this site exists.
 */

import * as Talents from './talents.js';
import * as Link from './link.js';
import * as Tooltip from './tooltip.js';
import { renderTree } from './tree.js';

const el = {
  picker: document.getElementById('class-picker'),
  trees: document.getElementById('trees'),
  spent: document.getElementById('points-spent'),
  max: document.getElementById('points-max'),
  left: document.getElementById('points-left'),
  stats: document.getElementById('stats'),
  warning: document.getElementById('link-warning'),
  highlight: document.getElementById('toggle-highlight'),
  onlyModified: document.getElementById('toggle-only-modified'),
  raw: document.getElementById('toggle-raw'),
  copy: document.getElementById('btn-copy'),
  reset: document.getElementById('btn-reset'),
};

const app = {
  index: null,
  classData: null,
  state: {},
  cache: new Map(),
};

async function loadJSON(path) {
  const response = await fetch(path);
  if (!response.ok) throw new Error(`${path}: ${response.status}`);
  return response.json();
}

async function loadClass(key) {
  if (app.cache.has(key)) return app.cache.get(key);
  const entry = app.index.classes.find(c => c.key === key);
  if (!entry) throw new Error(`unknown class: ${key}`);
  const data = await loadJSON(`./data/${entry.file}`);
  app.cache.set(key, data);
  return data;
}

function renderPicker(activeKey) {
  el.picker.innerHTML = '';
  for (const entry of app.index.classes) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `class-btn class-${entry.key}`;
    if (entry.key === activeKey) button.classList.add('active');
    button.textContent = entry.name;
    if (entry.modified) {
      const count = document.createElement('span');
      count.className = 'mod-count';
      count.textContent = entry.modified;
      count.title = `${entry.modified} talents changed on Alonecraft`;
      button.appendChild(count);
    }
    button.addEventListener('click', () => selectClass(entry.key, ''));
    el.picker.appendChild(button);
  }
}

function render() {
  const data = app.classData;
  document.body.dataset.class = data.key;

  el.trees.innerHTML = '';
  const ctx = {
    classData: data,
    state: app.state,
    iconBase: app.index.iconBase,
    highlight: el.highlight.checked,
    onlyModified: el.onlyModified.checked,
  };
  for (const tree of data.trees) {
    el.trees.appendChild(renderTree(tree, ctx));
  }

  const spent = Talents.totalPoints(data, app.state);
  el.spent.textContent = spent;
  el.max.textContent = Talents.MAX_POINTS;
  el.left.textContent = spent >= Talents.MAX_POINTS
    ? '(no points left)'
    : `(${Talents.MAX_POINTS - spent} left)`;

  const build = Link.encode(data, app.state);
  Link.writeHash(data.key, build);
}

function talentFromEvent(event) {
  const cell = event.target.closest('.talent');
  if (!cell) return null;
  const tree = app.classData.trees.find(
    t => String(t.tabId) === cell.dataset.tabId);
  if (!tree) return null;
  const talent = tree.talents.find(
    t => String(t.id) === cell.dataset.talentId);
  if (!talent) return null;
  return { cell, tree, talent };
}

function wireTreeEvents() {
  el.trees.addEventListener('click', event => {
    const reset = event.target.closest('.tree-reset');
    if (reset) {
      const tree = app.classData.trees.find(
        t => String(t.tabId) === reset.dataset.tab);
      if (tree) {
        app.state = Talents.resetTree(tree, app.state);
        clearWarning();
        render();
      }
      return;
    }
    const hit = talentFromEvent(event);
    if (!hit) return;
    app.state = event.shiftKey
      ? Talents.maxOut(app.classData, hit.tree, hit.talent, app.state)
      : Talents.addPoint(app.classData, hit.tree, hit.talent, app.state);
    clearWarning();
    render();
    refreshTooltip(hit);
  });

  el.trees.addEventListener('contextmenu', event => {
    const hit = talentFromEvent(event);
    if (!hit) return;
    event.preventDefault();
    app.state = Talents.removePoint(app.classData, hit.tree, hit.talent, app.state);
    clearWarning();
    render();
    refreshTooltip(hit);
  });

  el.trees.addEventListener('mouseover', event => {
    const hit = talentFromEvent(event);
    if (!hit) return;
    Tooltip.show(hit.cell, {
      classData: app.classData, tree: hit.tree,
      talent: hit.talent, state: app.state,
    });
  });

  el.trees.addEventListener('mouseout', event => {
    if (event.target.closest('.talent')) Tooltip.hide();
  });
}

/** After a click the DOM was rebuilt, so re-anchor the tooltip to the new cell. */
function refreshTooltip(previous) {
  const cell = el.trees.querySelector(
    `.talent[data-talent-id="${previous.talent.id}"]`);
  if (!cell) return Tooltip.hide();
  const tree = app.classData.trees.find(t => t.tabId === previous.tree.tabId);
  const talent = tree.talents.find(t => t.id === previous.talent.id);
  Tooltip.show(cell, {
    classData: app.classData, tree, talent, state: app.state,
  });
}

function clearWarning() {
  el.warning.hidden = true;
}

async function selectClass(key, build) {
  app.classData = await loadClass(key);
  app.state = build ? Link.decode(app.classData, build) : {};

  // A pasted link can describe something the rules forbid -- an older build
  // string, or a hand-edited URL.  Show it anyway (hiding it would be more
  // confusing) but say so.
  if (build && !Talents.isValidBuild(app.classData, app.state)) {
    el.warning.textContent =
      'This build is not reachable under the current talent rules — it may ' +
      'predate a change to these trees. Shown as-is.';
    el.warning.hidden = false;
  } else {
    clearWarning();
  }

  renderPicker(key);
  render();
}

function wireControls() {
  el.highlight.addEventListener('change', render);
  el.onlyModified.addEventListener('change', render);
  el.raw.addEventListener('change', () => {
    Tooltip.setShowRaw(el.raw.checked);
  });
  el.reset.addEventListener('click', () => {
    app.state = {};
    clearWarning();
    render();
  });
  el.copy.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(location.href);
      el.copy.textContent = 'Copied';
    } catch {
      el.copy.textContent = 'Press Ctrl+C';
    }
    setTimeout(() => { el.copy.textContent = 'Copy link'; }, 1500);
  });
  window.addEventListener('hashchange', () => {
    const { classKey, build } = Link.readHash();
    if (classKey && classKey !== app.classData?.key) selectClass(classKey, build);
  });
}

function renderStats() {
  const s = app.index.stats;
  const resolved = s.descriptions - s.descriptionsWithUnresolved;
  const pct = s.descriptions ? (100 * resolved / s.descriptions).toFixed(1) : '0';
  el.stats.textContent =
    `${s.talentsModified} of ${s.talents} talents differ from retail 3.3.5a. ` +
    `${resolved}/${s.descriptions} tooltips fully resolved (${pct}%). ` +
    `Data generated ${app.index.generated}.`;
}

async function main() {
  try {
    app.index = await loadJSON('./data/index.json');
  } catch (err) {
    el.trees.innerHTML =
      `<p class="error">Could not load talent data (${err.message}).<br>` +
      `If you opened this file directly, serve it instead: ` +
      `<code>python -m http.server 8000 --directory site</code></p>`;
    return;
  }

  el.max.textContent = app.index.maxPoints;
  renderStats();
  wireControls();
  wireTreeEvents();

  const { classKey, build } = Link.readHash();
  const known = app.index.classes.some(c => c.key === classKey);
  await selectClass(known ? classKey : app.index.classes[0].key,
                    known ? build : '');
}

main();
